NOM-01.code:
@layer components {
  .feed-page {
    display: flex;
    justify-content: center;
    width: 100%;
    padding-inline: var(--shelf-space-md);
    padding-block: var(--shelf-space-lg);
  }

  .feed-page-wrapper {
    width: 100%;
    max-width: var(--shelf-content-max-width);
  }

  .feed-page-heading {
    font-size: var(--shelf-font-size-xl);
    font-weight: var(--shelf-font-weight-bold);
    color: var(--shelf-color-text-primary);
    line-height: var(--shelf-line-height-tight);
    padding-block-end: var(--shelf-space-lg);
  }

  .feed-list {
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-md);
    list-style: none;
    padding: 0;
  }

  .feed-item {
    background-color: var(--shelf-color-surface);
    border-radius: var(--shelf-radius-md);
    border: var(--shelf-border-width) solid var(--shelf-color-border);
    padding: var(--shelf-space-md);
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-sm);
  }

  .feed-item-title {
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    color: var(--shelf-color-text-primary);
    line-height: var(--shelf-line-height-tight);
  }

  .feed-item-description {
    font-size: var(--shelf-font-size-sm);
    color: var(--shelf-color-text-secondary);
    line-height: var(--shelf-line-height-base);
  }
}

NOM-02.code:
@layer components {
  .project-grid {
    list-style: none;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(var(--shelf-project-grid-col-min), 1fr));
    gap: var(--shelf-project-grid-gap);
    padding: var(--shelf-project-grid-padding);
  }

  .project-card {
    background: var(--shelf-project-card-bg);
    border-radius: var(--shelf-project-card-radius);
    padding: var(--shelf-project-card-padding);
    gap: var(--shelf-project-card-gap);
    display: flex;
    flex-direction: column;
  }

  .project-card-name {
    color: var(--shelf-project-card-name-color);
    font-size: var(--shelf-project-card-name-size);
    font-weight: var(--shelf-project-card-name-weight);
    line-height: var(--shelf-project-card-name-line-height);
  }

  .project-card-description {
    color: var(--shelf-project-card-description-color);
    font-size: var(--shelf-project-card-description-size);
    line-height: var(--shelf-project-card-description-line-height);
  }
}

NOM-C1.code:
@layer components {
  .card-footer {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: var(--shelf-space-sm);
    padding-block-start: var(--shelf-space-sm);
    border-block-start: var(--shelf-borderWidth-thin) solid var(--shelf-borderColor-subtle);
  }

  .card-footer-timestamp {
    color: var(--shelf-fgColor-muted);
    font-size: var(--shelf-font-size-xs);
    font-weight: var(--shelf-font-weight-regular);
    line-height: var(--shelf-font-lineHeight-base);
  }

  .card-footer-action {
    margin-inline-start: auto;
    color: var(--shelf-fgColor-accent);
    font-size: var(--shelf-font-size-xs);
    font-weight: var(--shelf-font-weight-medium);
    background: none;
    border: none;
    padding: var(--shelf-space-xs) var(--shelf-space-sm);
    border-radius: var(--shelf-radius-md);
    cursor: pointer;
    transition: opacity var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter);
  }

  .card-footer-action:hover {
    opacity: var(--shelf-opacity-hover);
  }

  .card-footer-action:focus-visible {
    outline: var(--shelf-focusRing);
    outline-offset: var(--shelf-focusRing-offset);
  }

  .card-footer-action:active {
    opacity: var(--shelf-opacity-active);
  }

  .card-footer-action:disabled {
    opacity: var(--shelf-opacity-disabled);
    cursor: not-allowed;
  }
}
